 public static Label Label(string text,int size=10,bool bold=false){return new Label{Text=text,Font=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular),ForeColor=Text,BackColor=Color.Transparent,AutoSize=false,TextAlign=ContentAlignment.MiddleLeft};}
