}

sealed class CatalogDialog : Form {
 readonly List<CatalogItem> source;readonly ListBox list;readonly TextBox query;public CatalogItem Choice;
 public CatalogDialog(string title,List<CatalogItem> items){source=items;Text=title;BackColor=Theme.Bg;ForeColor=Theme.Text;ClientSize=new Size(760,540);MinimumSize=new Size(550,400);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);query=Theme.Input();query.SetBounds(18,18,724,28);query.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right;query.PlaceholderCompat(Lang.T("Название или ID"));list=new ListBox{BackColor=Theme.Panel,ForeColor=Theme.Text,BorderStyle=BorderStyle.None,IntegralHeight=false,Font=new Font("Segoe UI",10)};list.SetBounds(18,60,724,410);list.Anchor=AnchorStyles.Top|AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right;var select=Theme.Button(Lang.T("Выбрать"),Choose,true);select.SetBounds(542,488,200,36);select.Anchor=AnchorStyles.Bottom|AnchorStyles.Right;Controls.AddRange(new Control[]{query,list,select});query.TextChanged+=delegate{Filter();};list.DoubleClick+=delegate{Choose();};Filter();AcceptButton=select;}

 void Filter(){list.BeginUpdate();list.Items.Clear();string q=query.Text.Trim();foreach(var x in source.Where(x=>q=="" || x.id.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0 || x.name.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0).Take(1000))list.Items.Add(x);list.EndUpdate();if(list.Items.Count>0)list.SelectedIndex=0;}
 void Choose(){Choice=list.SelectedItem as CatalogItem;if(Choice!=null){DialogResult=DialogResult.OK;Close();}}
}
