 string ScopeLabel(Feature f){if(f.scope=="target")return Lang.T("Проверенная цель");if(f.scope=="family" || f.id.StartsWith("family_") || f.id.StartsWith("heal_family") || f.id.StartsWith("immortal_family"))return Lang.T("Правитель, супруги и дети");if(f.scope=="commanders")return Lang.T("Командиры моих армий");if(f.scope=="knights")return Lang.T("Мои рыцари");if(f.id.StartsWith("vassal_"))return Lang.T("Все вложенные вассалы");if(f.mass || f.scope=="counties" || f.scope=="provinces" || f.scope=="rulers")return Templates.Realm?Lang.T("Моя держава и вассалы"):Lang.T("Личный домен");return Lang.T("Мой правитель");}
 void DrawFeature(object sender,DrawItemEventArgs e){if(e.Index<0)return;var f=(Feature)features.Items[e.Index];bool active=session!=null && session.Active.Contains(f.id);using(var brush=new SolidBrush((e.State&DrawItemState.Selected)!=0?Color.FromArgb(57,53,43):Theme.Panel))e.Graphics.FillRectangle(brush,e.Bounds);using(var bold=new Font("Segoe UI",10,FontStyle.Bold))using(var small=new Font("Segoe UI",8)){var name=new Rectangle(e.Bounds.X+12,e.Bounds.Y+6,e.Bounds.Width-24,22);TextRenderer.DrawText(e.Graphics,(favorites.Contains(f.id)?"★ ":"")+f.title,bold,name,Theme.Text,TextFormatFlags.Left|TextFormatFlags.EndEllipsis);TextRenderer.DrawText(e.Graphics,f.kind!="action"?(active?Lang.T("ВКЛ"):Lang.T("ВЫКЛ")):Lang.T("ДЕЙСТВИЕ"),small,new Rectangle(e.Bounds.Right-92,e.Bounds.Y+25,82,16),active?Theme.Green:Theme.Muted,TextFormatFlags.Right);TextRenderer.DrawText(e.Graphics,ScopeLabel(f),small,new Rectangle(e.Bounds.X+12,e.Bounds.Y+27,350,16),Theme.Muted,TextFormatFlags.Left);}}
 void Filter(){Feature old=features.SelectedItem as Feature;string group=groups.SelectedItem as string,q=search.Text.Trim();features.BeginUpdate();features.Items.Clear();foreach(var f in Templates.Features.Where(f=>(group==null || group=="Все функции" || f.group==group || group=="Избранное" && favorites.Contains(f.id) || group=="Активные" && session!=null && session.Active.Contains(f.id) || group=="Разовые действия" && f.kind=="action") && (q=="" || (f.title+" "+f.description+" "+f.group+" "+Lang.T(f.group)).IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0)))features.Items.Add(f);features.EndUpdate();if(old!=null && features.Items.Contains(old))features.SelectedItem=old;else if(features.Items.Count>0)features.SelectedIndex=0;SelectFeature();}
 void SelectFeature(){selected=features.SelectedItem as Feature;chosen=null;if(selected==null){title.Text=Lang.T("Нет совпадений");description.Text="";ControlsState();return;}title.Text=selected.title;description.Text=selected.description+(selected.contains!=null?Lang.T("\nЗаменяет отдельные бонусы этого профиля."):"")+(selected.kind=="action"?Lang.T("\nИзменение останется в сохранении."):"");amount.Value=Math.Max(amount.Minimum,Math.Min(amount.Maximum,selected.value));objectInfo.Text=Lang.T("Объект не выбран");foreach(Control c in settings.Controls){if((string)c.Tag=="numeric")c.Visible=selected.kind=="action" && (selected.repeat || selected.body.Contains("$V") || selected.body.Contains("$PERCENT"));if((string)c.Tag=="province")c.Visible=selected.id=="building" || selected.id=="special";}browse.Visible=objectInfo.Visible=selected.arg!="";scopeNote.Visible=selected.kind!="action";scopeNote.Text=selected.scope=="knights"?Lang.T("Все текущие рыцари игрока.\nНовые рыцари получают бонус при проверке."):selected.scope=="commanders"?Lang.T("Бонус командирам поднятых армий игрока.\nПосле смены командира список обновится автоматически."):selected.scope=="target"?Lang.T("Применится к проверенной цели.\nВыключение снимет эффект с прежней цели, даже если выбор изменился."):selected.scope=="family"?Lang.T("Мой правитель, живые супруги и дети.\nСостав семьи обновляется во время игры."):selected.scope=="counties" || selected.scope=="provinces"?(Templates.Realm?Lang.T("Вся держава, включая вассалов.\nНовые владения получают бонус при проверке."):Lang.T("Личный домен текущего правителя.")):selected.scope=="rulers"?(Templates.Realm?Lang.T("Правитель и все вложенные вассалы."):Lang.T("Только мой правитель.")):Lang.T("Личный эффект текущему правителю.\nВыключение снимает только добавленное трейнером.");favorite.Text=favorites.Contains(selected.id)?"★":"☆";if(selected.requiresPack && session!=null && !session.PackV2)description.Text+=Lang.T("\nПакет 2 ожидает ручного перезапуска игры.");ControlsState();}
 void ControlsState(){if(campaign!=null)campaign.Enabled=!busy && !closing && (preview || session!=null);bool connected=preview || session!=null && session.Bridge!=null && session.Bridge.Alive;bool ready=connected && !busy && !closing && !connectionFault && selected!=null;connect.Enabled=!busy && !closing;refresh.Enabled=connected && !busy && !closing;clear.Enabled=connected && !busy && !closing;install.Enabled=!busy && !closing;inspect.Enabled=connected && !busy;inspectOther.Enabled=connected && !busy;browse.Enabled=selected!=null && selected.arg!="" && !busy;amount.Enabled=selected!=null && selected.kind=="action" && !busy;scopeToolbar.Enabled=!busy && !closing;measure.Enabled=connected && !busy;realmScope.Enabled=!busy;favorite.Enabled=selected!=null && !busy;apply.Enabled=ready && (!selected.requiresPack || preview || session!=null && session.PackV2) && (selected.scope!="target" || verifiedTarget!=0 || (session!=null && session.Active.Contains(selected.id))) && (!selected.other || verifiedOther!=0) && (selected.arg=="" || chosen!=null);apply.Text=selected==null?Lang.T("Выбери функцию"):selected.kind!="action"?(session!=null && session.Active.Contains(selected.id)?Lang.T("Выключить"):Lang.T("Включить")):Lang.T("Выполнить действие");groups.Enabled=!busy;features.Enabled=!busy;search.Enabled=!busy;people.Enabled=!busy;targetID.Enabled=!busy;otherID.Enabled=!busy;provinces.Enabled=!busy;provinceID.Enabled=!busy;}
 async void Run(Func<Task> job){if(busy)return;busy=true;ControlsState();try{await job();}catch(Exception e){Record(Lang.T("Ошибка: ")+e.Message);if(session!=null && session.LastReply!="")File.AppendAllText(Path.Combine(profile,"engine.log"),"\r\n"+DateTime.Now+"\r\n"+session.LastReply);footer.Text=e.Message;}finally{busy=false;ControlsState();}}
 async Task Attach(){
  if(preview)return;if(session!=null){if(session.Bridge!=null && session.Bridge.Alive)await session.Clear(false);session.Dispose();session=null;}var processes=Process.GetProcessesByName("ck3");if(processes.Length==0){status.Text=Lang.T("CK3 не запущена");Record(Lang.T("Ожидаю запущенную CK3 и одиночную кампанию"));return;}if(processes.Length>1)throw new InvalidOperationException(Lang.T("Найдено несколько CK3. Подключение отменено, чтобы не выбрать чужую кампанию."));status.Text=Lang.T("Проверяю версию и подключение…");var candidate=new TrainerSession(root);try{await candidate.Connect(processes[0].Id);session=candidate;connectionFault=false;session.Progress=delegate(string message){footer.Text=message;Record(message);};verifiedTarget=verifiedOther=0;UpdateView();Record(Lang.T("Подключение: PID ")+session.Bridge.Pid+" · "+session.State.Name+" ["+session.State.Player+"]");footer.Text="CK3 1.20.0.4 · "+Templates.Features.Count+Lang.T(" функций · ")+(session.PackV2?Lang.T("пакет 2 загружен"):Lang.T("пакет 2: нужен ручной перезапуск для профилей и защиты"))+" · "+(session.Bridge.MarkerReady?Lang.T("пакет 3 загружен"):Lang.T("пакет 3: перезапусти CK3 для действий над другими персонажами"));}catch{candidate.Dispose();status.Text=Lang.T("Подключение не выполнено");throw;}
 }
 async Task Read(bool broad){if(preview)return;await session.ReadSnapshot(broad);connectionFault=false;verifiedTarget=verifiedOther=0;UpdateView();Record(Lang.T("Обновлены правитель, семья и владения выбранного охвата"));}
 void UpdateView(){if(session!=null && session.State!=null){status.Text=Lang.T("Подключено · PID ")+session.Bridge.Pid+" · "+(session.PackV2?Lang.T("пакет 2 готов"):Lang.T("базовый пакет готов"));status.ForeColor=Theme.Green;player.Text=session.State.Name+"  ["+session.State.Player+"]";stats.Text=session.State.Metrics;people.Items.Clear();foreach(var p in session.State.People)people.Items.Add(p);if(people.Items.Count>0)people.SelectedIndex=0;provinces.Items.Clear();foreach(var p in session.State.Provinces)provinces.Items.Add(p);if(provinces.Items.Count>0)provinces.SelectedIndex=0;activeCount.Text=(session.Active.Count+session.WarScores.Count+session.CultureHeads.Count+session.Sieges.Count)+Lang.T(" активных");}if((string)groups.SelectedItem=="Активные")Filter();else features.Invalidate();ControlsState();}
 async Task Inspect(bool other){uint id;if(!UInt32.TryParse(other?otherID.Text:targetID.Text,out id) || id==0)throw new InvalidOperationException(Lang.T("Укажи числовой внутренний ID персонажа."));if(preview){if(other){verifiedOther=id;otherInfo.Text=Lang.T("Проверена демо-цель [")+id+"]";}else{verifiedTarget=id;targetInfo.Text=Lang.T("Проверена демо-цель [")+id+"]";}return;}var p=await session.Inspect(id);if(other){verifiedOther=id;otherInfo.Text=p.Name+" ["+id+"] · "+p.Details;}else{verifiedTarget=id;targetInfo.Text=p.Name+" ["+id+"] · "+p.Details;}Record(Lang.T("Проверена цель: ")+p.Name+" ["+id+"]");}
 void OpenCampaign(){if(busy || monitoring || closing || (!preview && session==null))return;busy=true;ControlsState();try{using(var f=new CampaignForm(session,root,preview))f.ShowDialog(this);}finally{busy=false;ControlsState();if(!preview)Run(async delegate{await Read(false);});}}
 void Favorite(){if(selected==null)return;if(!favorites.Add(selected.id))favorites.Remove(selected.id);File.WriteAllLines(Path.Combine(profile,"favorites.txt"),favorites.OrderBy(x=>x));Filter();}
 void Browse(){if(selected==null || selected.arg=="")return;using(var d=new CatalogDialog(selected.title,Templates.Catalogs[selected.arg]))if(d.ShowDialog(this)==DialogResult.OK){chosen=d.Choice;objectInfo.Text=chosen.name+"\n"+chosen.id;ControlsState();}}
 async Task Apply(){if(selected==null)return;Feature f=selected;if(preview){Record(Lang.T("Предпросмотр: ")+f.title);Sound(true);return;}if(f.kind!="action"){bool on=!session.Active.Contains(f.id);int n=await session.Toggle(f,on,verifiedTarget);Record(f.title+": "+(on?Lang.T("ВКЛ · объектов ")+n:Lang.T("ВЫКЛ"))+Lang.T(" · пересчётов ")+session.LastRecalculations);Sound(on);}else{uint prov;UInt32.TryParse(provinceID.Text,out prov);await session.Action(f,(int)amount.Value,chosen==null?"":chosen.id,prov,verifiedTarget,verifiedOther);Record(f.title+Lang.T(": команда выполнена движком")+(f.scope=="target"?Lang.T(" · цель ")+verifiedTarget:""));Sound(true);}if((string)groups.SelectedItem=="Активные")Filter();else features.Invalidate();activeCount.Text=(session.Active.Count+session.WarScores.Count+session.CultureHeads.Count+session.Sieges.Count)+Lang.T(" активных");footer.Text=Lang.T("Последнее действие подтверждено движком. Сохранение фиксирует постоянные изменения.");}
 void Record(string message){string line=DateTime.Now.ToString("HH:mm:ss")+"  "+message;history.AppendText(line+Environment.NewLine);history.SelectionStart=history.TextLength;history.ScrollToCaret();if(!preview)File.AppendAllText(Path.Combine(profile,"history.log"),DateTime.Now.ToString("yyyy-MM-dd ")+line+Environment.NewLine);}
 void Sound(bool enabled){if(!sound.Checked)return;try{new SoundPlayer(Path.Combine(root,"assets",enabled?"on.wav":"off.wav")).Play();}catch{}}
 void History(){var f=new Form{Text=Lang.T("История запусков и действий"),Size=new Size(900,620),BackColor=Theme.Bg,StartPosition=FormStartPosition.CenterParent};var box=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Dock=DockStyle.Fill,BackColor=Theme.Panel,ForeColor=Theme.Text,Font=new Font("Consolas",10)};box.Text=preview?history.Text:File.Exists(Path.Combine(profile,"history.log"))?File.ReadAllText(Path.Combine(profile,"history.log")):history.Text;box.SelectionStart=box.TextLength;box.ScrollToCaret();f.Controls.Add(box);f.Show(this);}
 static string FindGame(){
  var libraries=new List<string>();
  try{using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Valve\Steam")){string steam=key==null?null:key.GetValue("SteamPath") as string;
   if(steam!=null){libraries.Add(steam);string vdf=Path.Combine(steam,@"steamapps\libraryfolders.vdf");
    if(File.Exists(vdf))foreach(var line in File.ReadAllLines(vdf)){var m=System.Text.RegularExpressions.Regex.Match(line,"\"path\"\\s+\"(.+)\"");if(m.Success)libraries.Add(m.Groups[1].Value.Replace(@"\\",@"\"));}}}}catch{}
  foreach(var library in libraries){string game=Path.Combine(library,@"steamapps\common\Crusader Kings III");if(File.Exists(Path.Combine(game,@"binaries\ck3.exe")))return game;}
  return null;
 }
 void Install(){try{string game=session!=null?session.Bridge.GamePath:FindGame();if(game==null)throw new InvalidOperationException(Lang.T("Папка CK3 не найдена. Запусти игру — трейнер возьмёт путь из процесса."));string[] sources={"zz_ck3t_personal_trainer.txt","ck3t_l_russian.yml","zz_ck3t_v2_modifiers.txt","zz_ck3t_v2_traits.txt","ck3t_v2_l_russian.yml","zz_ck3t_v3_traits.txt","ck3t_v3_l_russian.yml","ck3t_l_english.yml","ck3t_v2_l_english.yml","ck3t_v3_l_english.yml"};string[] dest=sources.Select(x=>Path.Combine(game,x.EndsWith(".yml")?(x.Contains("english")?@"game\localization\english\ck3t":@"game\localization\russian\ck3t"):x.Contains("traits")?@"game\common\traits":@"game\common\modifiers",x)).ToArray();for(int i=0;i<sources.Length;i++){string source=Path.Combine(root,"pack",sources[i]);if(File.Exists(dest[i]) && !File.ReadAllBytes(dest[i]).SequenceEqual(File.ReadAllBytes(source)))throw new InvalidOperationException(Lang.T("Файл пакета отличается от нашего. Перезапись отменена: ")+dest[i]);Directory.CreateDirectory(Path.GetDirectoryName(dest[i]));File.Copy(source,dest[i],true);}Record(Lang.T("Пакет установлен. Для первой загрузки нужен ручной перезапуск CK3."));footer.Text=Lang.T("После первой установки сохрани кампанию и самостоятельно перезапусти CK3.");}catch(Exception e){Record(Lang.T("Установка: ")+e.Message);footer.Text=e.Message;}}
 async Task Monitor(){if(busy || closing || monitoring || preview || session==null)return;monitoring=true;try{if(!session.Bridge.Alive){session.Dispose();session=null;status.Text=Lang.T("CK3 закрыта · ожидание подключения");verifiedTarget=verifiedOther=0;activeCount.Text=Lang.T("Нет связи");ControlsState();return;}uint was=session.State.Player;long state=session.Bridge.GameState;session.Bridge.Refresh();if(was!=session.Bridge.PlayerID || state!=session.Bridge.GameState || session.State.PlayerPointer!=session.Bridge.PlayerPointer){busy=true;ControlsState();await session.Clear(false);await Read(false);await session.Campaign.Stories.Revalidate();Record(Lang.T("Правитель / кампания сменились: прежние бонусы сняты, сценарии проверены"));}else if((session.Active.Count>0 || session.WarScores.Count>0 || session.CultureHeads.Count>0 || session.Sieges.Count>0 || session.Campaign!=null && session.Campaign.Stories.HasStories) && DateTime.UtcNow>=renew){busy=true;ControlsState();await session.Renew();renew=DateTime.UtcNow.AddSeconds(30);}}catch(Exception e){connectionFault=true;status.Text=Lang.T("Связь требует проверки: ")+e.Message;apply.Enabled=false;}finally{monitoring=false;busy=false;ControlsState();}}
 async void OnClosing(object sender,FormClosingEventArgs e){if(allowClose)return;e.Cancel=true;if(closing)return;if(busy){footer.Text=Lang.T("Дождись ответа на текущую команду, затем закрой приложение.");return;}closing=true;timer.Stop();ControlsState();try{if(session!=null && session.Bridge!=null && session.Bridge.Alive){status.Text=Lang.T("Снимаю бонусы перед закрытием…");await session.Clear(false);Record(Lang.T("Закрытие: личные бонусы сняты, сценарии сохранены, игра продолжает работать"));}}catch(Exception ex){Record(Lang.T("Закрытие: ")+ex.Message);}finally{if(session!=null)session.Dispose();allowClose=true;Close();}}
 void Mock(){status.Text=Lang.T("ПРЕДПРОСМОТР · подключение к игре отключено");status.ForeColor=Theme.Gold;player.Text=Lang.T("Мой правитель · семья · личные владения и армии");stats.Text=PreviewStats();people.Items.Add(new Person{ID=13076,Name="Цуй Аньцянь",Role="Мой правитель"});people.Items.Add(new Person{ID=17739,Name="Цуй И",Role="Ребёнок"});people.SelectedIndex=0;footer.Text=Lang.T("Все цели проверяются перед действием. Кнопка очистки снимает переключатели; постоянные изменения остаются в сохранении.");Record(Lang.T("Приложение готово: выбери функцию и её параметры"));ControlsState();}
}

static class Program {
 [STAThread]static void Main(string[] args){bool mock=args.Contains("--preview") || args.Contains("--screenshot") || args.Contains("--campaign-screenshot") || args.Contains("--mode-screenshot");string screenshot="";int n=Array.IndexOf(args,"--screenshot");if(n<0)n=Array.IndexOf(args,"--live-screenshot");if(n>=0 && n+1<args.Length)screenshot=Path.GetFullPath(args[n+1]);bool acquired;using(var mutex=new System.Threading.Mutex(true,@"Local\CK3PersonalTrainer",out acquired)){if(!acquired && !mock){MessageBox.Show(Lang.T("CK3 Trainer уже запущен."));return;}try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);int mi=Array.IndexOf(args,"--mode-screenshot");if(mi>=0 && mi+1<args.Length){Templates.Load(AppDomain.CurrentDomain.BaseDirectory);var catalog=new CampaignEngine(null,AppDomain.CurrentDomain.BaseDirectory);var mode=new CampaignModeDashboard(null,catalog,true);string image=Path.GetFullPath(args[mi+1]);mode.Shown+=async delegate{await Task.Delay(400);using(var bitmap=new Bitmap(mode.Width,mode.Height)){mode.DrawToBitmap(bitmap,new Rectangle(0,0,mode.Width,mode.Height));bitmap.Save(image);}mode.Close();};mode.StartPosition=FormStartPosition.Manual;mode.Location=new Point(-16000,-16000);Application.Run(mode);return;}int ci=Array.IndexOf(args,"--campaign-screenshot");if(ci>=0 && ci+1<args.Length){Templates.Load(AppDomain.CurrentDomain.BaseDirectory);var editor=new CampaignForm(null,AppDomain.CurrentDomain.BaseDirectory,true,Path.GetFullPath(args[ci+1]));int ai=Array.IndexOf(args,"--campaign-action");if(ai>=0 && ai+1<args.Length)editor.PickAction(args[ai+1]);editor.StartPosition=FormStartPosition.Manual;editor.Location=new Point(-16000,-16000);Application.Run(editor);return;}var form=new TrainerForm(mock,screenshot);if(screenshot!=""){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-16000,-16000);}Application.Run(form);}catch(Exception ex){MessageBox.Show(ex.Message,"CK3 Trainer");}}}
}
